// Copies the semantic roles generated by HtmlForgeX. This only selects declarations; it never derives colours.
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sourceIndex = process.argv.indexOf("--source");
if (sourceIndex < 0 || !process.argv[sourceIndex + 1]) throw new Error("Supply --source <HtmlForgeX checkout> to import generated tokens.");
const source = path.resolve(process.argv[sourceIndex + 1]);
const relative = "HtmlForgeX/Resources/Styles/hfx-tokens.css";
const css = fs.readFileSync(path.join(source, relative), "utf8").replaceAll("\r\n", "\n");
const resolvedText = fs.readFileSync(path.join(source, "HtmlForgeX/Resources/Tokens/hfx-tokens.resolved.json"), "utf8");
const resolved = JSON.parse(resolvedText);
const names = new Set();
const reference = /var\(\s*(--hfx-[a-z0-9-]+)\s*[,)]/g;
function collect(text) { for (const match of text.matchAll(reference)) names.add(match[1]); }
function readSources(directory) {
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const full = path.join(directory, entry.name);
    if (entry.isDirectory() && !["bin", "obj", "node_modules"].includes(entry.name)) readSources(full);
    else if (entry.isFile() && /\.(?:css|js|cs|html)$/.test(entry.name) && (full.includes(".source" + path.sep) || full.includes("CanopyX.Examples"))) collect(fs.readFileSync(full, "utf8"));
  }
}
readSources(path.join(root, "CanopyX.Html/Assets"));
readSources(path.join(root, "CanopyX.Examples"));
// Built-in status fallbacks and categorical colours keep the shared order. Named tones come from their host.
for (const status of ["good", "warn", "bad", "info", "neutral"]) {
  for (const role of ["fg", "bg"]) names.add(`--hfx-color-status-${status}-${role}`);
}
for (let index = 1; index <= 6; index++) names.add("--hfx-color-series-" + index);
const declarations = [...css.matchAll(/(--hfx-[a-z0-9-]+)\s*:\s*([^;{}]+);/g)];
// Optional component roles use initial so a theme island can supply their semantic fallback at the use site.
const fallbackDefault = (name, value) => value.trim() === "initial" ? resolved.components[name.replace("--hfx-", "")] : value.trim();
let count;
do {
  count = names.size;
  for (const match of declarations) if (names.has(match[1])) collect(fallbackDefault(match[1], match[2]) || "");
} while (count !== names.size);
const missing = [...names].filter(name => !declarations.some(match => match[1] === name));
if (missing.length) throw new Error("Shared generator does not define: " + missing.join(", "));

// Fallbacks are values used inside var(), never declarations of shared roles on a host.
const defaults = Object.fromEntries([...declarations].reverse().map(match => [match[1], match[2].trim()]));
const values = {};
function fallback(name, chain = []) {
  if (values[name]) return values[name];
  if (chain.includes(name)) throw new Error("Cyclic shared token: " + name);
  const key = name.replace("--hfx-color-", ""), light = resolved.themes.evotec.light[key], dark = resolved.themes.evotec.dark[key];
  let value = name.startsWith("--hfx-color-") && light ? (light === dark ? light : `light-dark(${light},${dark})`) : fallbackDefault(name, defaults[name]);
  if (!value) throw new Error("No fallback for " + name);
  const metric = name.replace("--hfx-", ""), comfortable = resolved.density.comfortable[metric], compact = resolved.density.compact[metric];
  if (comfortable && compact && comfortable !== compact && /^\d+px$/.test(comfortable) && /^\d+px$/.test(compact)) {
    value = `calc(${comfortable} - var(--cx-compact,0) * ${parseFloat(comfortable) - parseFloat(compact)}px)`;
  }
  if (metric === "control-font-size") value = "calc(var(--hfx-type-body-size) - var(--cx-compact,0) * .0625rem)";
  value = value.replace(/var\((--hfx-[a-z0-9-]+)\)/g, (_, dependency) => `var(${dependency},${fallback(dependency, [...chain, name])})`);
  values[name] = value;
  return value;
}
for (const name of [...names].sort()) fallback(name);
const target = path.join(root, "CanopyX.Html/Assets/Shared/canopyx-fallbacks.json");
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(target, JSON.stringify(values, null, 2) + "\n");
fs.copyFileSync(path.join(source, "Build/hfx-css-lint.rules.json"), path.join(root, "Build/design-token-lint.rules.json"));
fs.writeFileSync(path.join(root, "Build/design-token-source.json"), JSON.stringify({ repository: "EvotecIT/HtmlForgeX", path: relative,
  sha256: crypto.createHash("sha256").update(css).digest("hex"), resolvedSha256: crypto.createHash("sha256").update(resolvedText).digest("hex"), tokens: [...names].sort() }, null, 2) + "\n");
console.log(`Imported ${names.size} shared fallback values without palette declarations.`);

// The real shared stylesheet is a test-only host fixture, never a CanopyX runtime asset.
fs.copyFileSync(path.join(source, relative), path.join(root, "tests/fixtures/hfx-role-host.css"));
